config.starterHcl:
resource "cloud_security_group" "web" {
  name = "grades-sg"
  ingress {
    port   = 443
    source = "0.0.0.0/0"
  }
  ingress {
    port   = 22
    source = "10.0.0.0/16"
  }
}

resource "cloud_vm" "web" {
  name           = "grades-web"
  region         = "af-west-1"
  size           = "small"
  security_group = cloud_security_group.web.id
}

resource "cloud_bucket" "exports" {
  name      = "grades-exports"
  encrypted = true
  public    = false
}
